      hu: ["Egy 13. századi mecsetnek ad otthont", "Körülbelül 30 díszes korallkő síroszlopot tartalmaz", "A szuahéli partvidék egykori sirázi kulturális központja", "Kínai porcelánleletek bizonyítják a távolsági kereskedelmet", "Egész évben látogatható nemzeti emlékhelyként", "Csupán 5 km-re délre fekszik a történelmi Bagamoyótól"],
      ro: ["Găzduiește o moschee ce datează din secolul al XIII-lea", "Include aproximativ 30 de morminte cu piloni din piatră de coral", "Fost centru al culturii Shiraz de pe coasta Swahili", "Descoperirile de porțelan chinezesc atestă rute comerciale lungi", "Deschis vizitatorilor pe tot parcursul anului ca monument național", "Situat la doar 5 km sud de orașul istoric Bagamoyo"],
      en: ["Home to a mosque dating back to the 13th century", "Contains approximately 30 elaborate coral stone pillar tombs", "Former center of Shiraz culture on the Swahili Coast", "Finds of Chinese porcelain prove long-distance trade routes", "Open to visitors year-round as a national monument", "Located just 5 km south of the historic town of Bagamoyo"],
      es: ["Un sitio arqueológico que alberga un asentamiento persa del siglo XIII.", "Situado en el Estado de Tanzania, en África Oriental, entre el Océano Índico y la región de los Grandes Lagos.", "La región pertenece a la zona climática tropical con una marcada estación seca y lluviosa.", "Accesible a través de la red nacional de carreteras que parte de Dar es Salaam y Dodoma."],
