      fr: ["Les restes fascinants d'un système agricole complexe et d'un établissement de l'âge du fer dans la grande vallée du Rift.", "Situé dans l'État de Tanzanie, entre l'océan Indien et la région des Grands Lacs.", "La région appartient à la zone climatique tropicale avec une saison des pluies et une saison sèche marquées.", "Accessible par le réseau routier national au départ de Dar es Salaam et Dodoma."],
