      hu: ["Több mint 40 siráz sírhelyet rejt", "Nagy mecset romja", "Vasco da Gama 1499-ben meglátogatta", "A virágzó szuahéli civilizáció tanúja"],
      ro: ["Adăpostește peste 40 de morminte shirazi", "Ruina unei mari moschei", "A fost vizitat de Vasco da Gama în 1499", "Mărturie a înfloritoarei civilizații swahili"],
      en: ["Hosts over 40 Shirazi tombs", "Large mosque ruin", "Visited by Vasco da Gama in 1499", "Testament to the flourishing Swahili civilization"],
      es: ["Alberga más de 40 tumbas de Shiraz", "Ruinas de la gran mezquita", "Visitada por Vasco da Gama en 1499", "Testimonio de la floreciente civilización suajili"],
      pt: ["Abriga mais de 40 túmulos de Xiraz", "Ruínas da grande mesquita", "Visitada por Vasco da Gama em 1499", "Testemunho da florescente civilização suaíli"],
      fr: ["Abrite plus de 40 tombes Shiraz", "Ruines de la grande mosquée", "Visitée par Vasco de Gama en 1499", "Témoignage de la florissante civilisation swahilie"],
