    facts: {
      de: ["Eröffnet im Jahr 1940 als King George V Memorial Museum", "Beherbergt den Schädel des Zinjanthropus (Paranthropus boisei)", "Dokumentiert die Sklavenhandelsgeschichte", "Sammlung klassischer Autos"],
      hu: ["1940-ben nyílt meg King George V Memorial Museum néven", "A Zinjanthropus (Paranthropus boisei) koponyáját őrzi", "Dokumentálja a rabszolga-kereskedelem történetét", "Klasszikus autók gyűjteménye"],
      ro: ["Deschis în 1940 ca Muzeul Memorial Regele George al V-lea", "Adăpostește craniul lui Zinjanthropus (Paranthropus boisei)", "Documentează istoria comerțului cu sclavi", "Colecție de mașini clasice"],
      en: ["Opened in 1940 as King George V Memorial Museum", "Houses the skull of Zinjanthropus (Paranthropus boisei)", "Documents the history of the slave trade", "Collection of classic cars"],
      es: ["Inaugurado en 1940 como King George V Memorial Museum", "Alberga el cráneo del Zinjanthropus (Paranthropus boisei)", "Documenta la historia del comercio de esclavos", "Colección de coches clásicos"],
      pt: ["Inaugurado em 1940 como King George V Memorial Museum", "Alberga o crânio do Zinjanthropus (Paranthropus boisei)", "Documenta a história do comércio de escravos", "Coleção de carros clássicos"],
      fr: ["Inauguré en 1940 sous le nom de King George V Memorial Museum", "Abrite le crâne du Zinjanthropus (Paranthropus boisei)", "Documente l'histoire de la traite négrière", "Collection de voitures anciennes"],
    }, image: "/poi-images/tz-national-museum-history-v2.webp",
    descriptionAdvanced: {
      de: "Das Nationalmuseum von Tansania in Dar es Salaam wurde 1934 gegründet und 1940 für die Öffentlichkeit eröffnet. Ursprünglich als Gedenkstätte für König Georg V. konzipiert, hat es sich zum wichtigsten Zentrum für die Bewahrung des kulturellen und natürlichen Erbes des Landes entwickelt. Die Ausstellungen decken ein breites Spektrum ab, von der frühen Menschheitsgeschichte bis zur Unabhängigkeitsbewegung. Ein Highlight ist der Bereich für Paläoanthropologie, der bedeutende Fossilienfunde aus der Olduvai-Schlucht beherbergt, darunter den berühmten 'Zinjanthropus'-Schädel (Paranthropus boisei), der über 1,75 Millionen Jahre alt ist. Weitere Galerien widmen sich der Geschichte des Sklavenhandels, der deutschen und britischen Kolonialzeit sowie der traditionellen Kunst und den Bräuchen der verschiedenen ethnischen Gruppen Tansanias. Das Museum spielt eine entscheidende Rolle in der Bildung und Forschung und bewahrt auch die offiziellen Staatskarossen von Julius Nyerere, dem ersten Präsidenten des Landes, auf.",
      hu: "A Tanzániai Nemzeti Múzeum Dar es-Salaamban 1934-ben alakult, és 1940-ben nyitotta meg kapuit a nagyközönség előtt. Eredetileg V. György brit király emlékére hozták létre, de azóta az ország kulturális és természeti örökségének legfontosabb őrzőhelyévé vált. A kiállítások az emberiség korai történetétől a függetlenségi mozgalomig terjednek. A múzeum egyik legértékesebb része a paleoantropológiai gyűjtemény, amely az Olduvai-szakadékból származó világhírű fosszíliákat mutatja be, köztük az 1,75 millió éves 'Zinjanthropus' koponyát (Paranthropus boisei). További galériák foglalkoznak a rabszolga-kereskedelem történetével, a német és brit gyarmati korszakkal, valamint Tanzánia számos etnikai csoportjának hagyományos művészetével és szokásaival. Az intézmény kulcsszerepet játszik az oktatásban és a kutatásban, emellett itt őrzik Julius Nyerere-nek, az ország első elnökének hivatalos állami autóit is.",
      ro: "Muzeul Național al Tanzaniei din Dar es Salaam a fost fondat în 1934 și deschis publicului în 1940. Conceput inițial ca un memorial pentru Regele George al V-lea, acesta a devenit cel mai important centru pentru conservarea patrimoniului cultural și natural al țării. Expozițiile acoperă un spectru larg, de la istoria timpurie a omenirii până la mișcarea de independență. Un punct culminant este secțiunea de paleoantropologie, care găzduiește descoperiri de fosile semnificative din defileul Olduvai, inclusiv faimosul craniu 'Zinjanthropus' (Paranthropus boisei), vechi de peste 1,75 milioane de ani. Alte galerii sunt dedicate istoriei comerțului cu sclavi, perioadelor coloniale germană și britanică, precum și artei tradiționale și obiceiurilor diverselor grupuri etnice din Tanzania. Muzeul joacă un rol crucial în educație și cercetare, păstrând de asemenea mașinile oficiale de stat ale lui Julius Nyerere, primul președinte al țării.",
      en: "The National Museum of Tanzania in Dar es Salaam was established in 1934 and opened to the public in 1940. Originally conceived as a memorial to King George V, it has evolved into the nation's primary center for preserving cultural and natural heritage. The exhibits cover a vast range of topics, from early human evolution to the struggle for independence. A major highlight is the paleoanthropology section, which houses significant fossil finds from Olduvai Gorge, including the world-famous 'Zinjanthropus' skull (Paranthropus boisei), dating back over 1.75 million years. Other galleries are dedicated to the history of the Indian Ocean slave trade, the German and British colonial eras, and the traditional arts and customs of Tanzania's diverse ethnic groups. The museum plays a vital role in education and research, and also features a collection of official state vehicles used by Julius Nyerere, the country's first president.",
      es: "El museo más grande del país, que exhibe hallazgos fósiles significativos de la evolución humana y testimonios de la historia colonial y precolonial. Inaugurado en 1940 como el King George V Memorial Museum, alberga el famoso cráneo del Zinjanthropus (Paranthropus boisei). Además, documenta la historia del comercio de esclavos y cuenta con una colección de coches clásicos. Este sitio es uno de los puntos característicos de Tanzania, país de África Oriental conocido por el Kilimanjaro, el Serengueti, el Cráter del Ngorongoro, los Grandes Lagos, el archipiélago de Zanzíbar y su riqueza en café, clavo y oro, ofreciendo una visión profunda de la identidad regional.",
      pt: "O maior museu do país, que exibe achados fósseis significativos da evolução humana e testemunhos da história colonial e pré-colonial. Inaugurado em 1940 como o King George V Memorial Museum, alberga o famoso crânio do Zinjanthropus (Paranthropus boisei). Além disso, documenta a história do comércio de escravos e possui uma coleção de carros clássicos. Este local é um dos pontos característicos da Tanzânia, um país da África Oriental definido pelo Kilimanjaro, Serengeti, Cratera de Ngorongoro, Grandes Lagos, o arquipélago de Zanzibar e a sua riqueza em café, cravinho e ouro, oferecendo um vislumbre da identidade regional.",
      fr: "Le plus grand musée du pays, qui expose d'importants fossiles de l'évolution humaine ainsi que des témoignages de l'histoire coloniale et précoloniale. Inauguré en 1940 sous le nom de King George V Memorial Museum, il abrite le crâne du Zinjanthropus (Paranthropus boisei). Il documente également l'histoire de la traite négrière et possède une collection de voitures anciennes. Ce lieu est l'un des points caractéristiques de la Tanzanie, pays d'Afrique de l'Est marqué par le Kilimandjaro, le Serengeti, le cratère du Ngorongoro, les Grands Lacs, l'archipel de Zanzibar et ses richesses en café, girofle et or, offrant un aperçu de l'identité régionale.",
    },
