      hu: ["A múzeumot 1934-ben alapították Dar es-Salaam központjában.", "Itt látható az Olduvai-szakadékból származó híres Zinjanthropus-koponya.", "Az intézmény eredeti neve King George V Memorial Museum volt.", "A gyűjtemény része több tucat hagyományos szuahéli dhow hajómodell.", "A múzeum udvarán Julius Nyerere egykori elnöki autói láthatóak.", "A kiállítások részletesen bemutatják a német gyarmati uralom éveit."],
