      en: ["The museum was founded in 1934 and opened in 1940.", "It houses the 1.75-million-year-old Zinjanthropus skull from Olduvai.", "The original structure was the King George V Memorial Museum.", "Exhibits detail the impact of the slave trade on the Swahili coast.", "The collection includes the state cars of President Julius Nyerere.", "It serves as the main repository for Tanzanian ethnographic artifacts."],
