      fr: ["Le musée national le plus important de Tanzanie.", "Située en Tanzanie, entre l'océan Indien et la région des Grands Lacs.", "La région bénéficie d'un climat tropical avec des saisons humides et sèches marquées.", "Accessible par le réseau routier national depuis Dar es Salaam et Dodoma."],
