      pt: ["Um antigo palácio do sultão em Zanzibar, conhecido como o edifício mais alto em Stone Town e o primeiro na África Oriental com eletricidade e elevador.", "Localizado no estado da Tanzânia, entre o Oceano Índico e a região dos Grandes Lagos.", "A região pertence à zona climática tropical com uma marcada estação chuvosa e seca.", "Acessível através da rede rodoviária nacional que parte de Dar es Salaam e Dodoma."],
      fr: ["Un ancien palais du sultan à Zanzibar, connu comme le plus haut bâtiment de Stone Town et le premier en Afrique de l'Est à disposer de l'électricité et d'un ascenseur.", "Situé dans l'État de Tanzanie, entre l'océan Indien et la région des Grands Lacs.", "La région appartient à la zone climatique tropicale avec une saison des pluies et une saison sèche marquées.", "Accessible par le réseau routier national au départ de Dar es Salaam et Dodoma."],
